      'trio-desc-p2':        'Forged Chain TRIO (pitch 102 mm.) and Forged Chain UNO (pitch 142 mm.) simply able to handle well with high load capacity as well as wear &amp; tear endurance against rail guide operation, high temperature, and dust environment.',
