      /* ---------- Sugar Mill Chains &mdash; section 3 ---------- */
      'sgm-s3-eyebrow': 'Process Coverage',
      'sgm-s3-h2':      'Full Sugar Mill Chain Solutions',
      'sgm-s3-intro':   'From raw cane intake to packaged sugar &mdash; MPC supplies the right chain for every stage of the milling process.',
      'sgm-step1-title': 'Raw Materials Handling',
      'sgm-step1-body':  'Heavy cane carrier chains and slat conveyors engineered to handle bulk sugar cane intake from field to mill.',
      'sgm-step2-title': 'Juicing Process',
      'sgm-step2-body':  'Drive and conveyor chains for roller mills and crushers &mdash; built to withstand high torque and continuous cyclic loading.',
      'sgm-step3-title': 'Bagasse Conveying',
      'sgm-step3-body':  'Bagasse feeder and conveyor chains designed for wet, fibrous, and abrasive post-extraction residue handling.',
      'sgm-step4-title': 'Settling &amp; Evaporation',
      'sgm-step4-body':  'Drive chains for juice clarifiers, evaporator drives, and settling tank mechanisms in the purification stage.',
      'sgm-step5-title': 'Drying &amp; Screening',
      'sgm-step5-body':  'Conveyor chains for sugar drying drums, vibrating screens, and rotary equipment in the crystallisation stage.',
      'sgm-step6-title': 'Packing Line',
      'sgm-step6-body':  'Precision roller chains for bagging machines, packaging conveyors, and final product dispatch systems.',
      'sgm-pg-s2-intro': 'A comprehensive selection of HS Chain products engineered for every stage of sugar production &mdash; from raw cane intake to finished product handling.',
      'sgm-pg-body-p1':  'We have an overall comprehension towards the procedures and equipment of sugar making industry using sugar cane and beet as the raw materials; Nowadays, we also have rich design experience and manufacturing technology, and we can provide special sugar making machine chains with the function of transmission, hoisting and conveying for worldwide sugar making industry in the whole processing system, including raw materials, juicing, settling, evaporation, drying, screening, and packing.',
      'sgm-pg-pull':     'Full process coverage &mdash; from raw material intake to finished sugar packing &mdash; with purpose-built chains for every stage of modern sugar production.',
      'sgm-pg-h1-plain': 'Sugar Mill Industry Chains',
      'sgm-cta-h3':      'Looking for sugar mill chain solutions?',
      'sgm-cta-p':       'Contact MPC for technical selection, pricing, and supply of HS sugar mill chains across Southeast Asia.',
