      'uno-pg-desc-text':   '<p>โซ่ UNO ผลิตจากโรงงาน OEM ชั้นนำในประเทศจีน ที่รับผลิตให้แบรนด์ระดับโลกจากยุโรป สหรัฐอเมริกา และญี่ปุ่น ทุกกระบวนการผลิตผ่านการควบคุมคุณภาพตามมาตรฐาน ISO 9001, DIN, JIS พร้อมระบบ Q.A. (ประกันคุณภาพ) และ Q.C. (ควบคุมคุณภาพ) อย่างเข้มงวด</p><p>กระบวนการเริ่มจากการคัดเลือกเหล็กคุณภาพสูง ผ่านการตัดและปั๊มด้วยเครื่องจักรอัตโนมัติ จากนั้นอบชุบความร้อนแยกเฉพาะแต่ละชิ้นส่วน ไม่ว่าจะเป็นพิน บุช แผ่น หรือลูกกลิ้ง เพื่อให้ได้ความแข็งที่เหมาะสมกับงานแต่ละประเภท ยืดอายุการใช้งานได้อย่างมีนัยสำคัญ นอกจากนี้ยังผ่านกระบวนการพ่นทรายบนแผ่นโซ่เพื่อเพิ่มความทนทานต่อการสึกหรอและอุณหภูมิสูง</p><p>การ Pre-Stretch คือขั้นตอนสำคัญที่ช่วยป้องกันโซ่บิด ลดการยืดตัวในช่วงแรกของการใช้งาน และเพิ่มความสามารถรับแรงดึง</p><p class="pull">โซ่ UNO คือตัวเลือกที่ลงตัวสำหรับงานที่ต้องการความทนทานสูงในราคาที่คุ้มค่า</p>',
