      'dbo-desc-text':      '<p>โซ่ลำเลียงระยะพิทช์เล็กใช้งานได้หลากหลายอุตสาหกรรม ทั้งบรรจุภัณฑ์ อาหาร เครื่องสำอาง ยา และการผลิตทั่วไป ผลิตจากชิ้นส่วนโซ่ลูกกลิ้งมาตรฐาน บวกกับอุปกรณ์เสริมที่ออกแบบพิเศษสำหรับระบบลำเลียงโดยเฉพาะ</p><ul><li>อุปกรณ์เสริมแบบมาตรฐานและแบบ Wide Contour มีให้เลือกหลายขนาด</li><li>โซ่ประกอบสำเร็จและอะไหล่พร้อมจัดส่งจากสต็อก</li><li>วัสดุครอบคลุมเหล็กกล้าคาร์บอนคุณภาพสูง สเตนเลส พลาสติกวิศวกรรม พร้อมการเคลือบผิวป้องกัน (นิกเกิล สังกะสี โครเมียม และ Dacrotized Coating)</li><li>อุปกรณ์เสริมพิเศษนอกแคตตาล็อกสั่งผลิตได้ตามความต้องการ</li></ul><p class="pull">Dong Bo ผู้ผลิตโซ่ชั้นนำจากเกาหลีกว่า 45 ปี พร้อมช่วยคุณเลือกระบบที่เหมาะสมที่สุดสำหรับสายพานลำเลียงของคุณ</p>',
