      'sug-c6-h3':        '⚙️ สายพานยาว แรงดึงสูง',
      'sug-c6-p':         'สายพานขนส่งอ้อยอาจยาว 50–100 เมตร พร้อมแรงดึงโซ่สูงจากน้ำหนักวัสดุและโครงสร้างสายพาน ความสม่ำเสมอของพิตช์และความแข็งแรงต่อความล้าสูงเป็นสิ่งขาดไม่ได้',
      'sug-prod-h2':      'โซ่สำหรับโรงงานน้ำตาล',
      'sug-prod-p':       'โซ่ที่ทีมของเราเลือกใช้บ่อยที่สุดสำหรับโรงงานน้ำตาลทั่วประเทศไทย — ตั้งแต่รับอ้อยจนถึงขนส่งกากน้ำตาล',
      'sug-p1-h3':        'โซ่ขนส่งอ้อย',
      'sug-p1-p':         'โซ่งานหนักสำหรับสายพานขนส่งอ้อย — หัวใจหลักของทุกโรงงานน้ำตาล มีหลายขนาดพิตช์และแรงดึงสูงสุด เพื่อให้เหมาะกับความกว้างสายพานและกำลังการผลิต พร้อมเกรดทนการกัดกร่อนสำหรับสภาพแวดล้อมเปียก',
      'sug-p2-h3':        'TRIO Heavy Forged Chain (P.102mm)',
      'sug-p2-p':         'TRIO Chain ของ MPC พิตช์ 102mm ใช้ในโรงงานน้ำตาลสำหรับงานลำเลียงหนักที่สุด ภาคตัดขวางขนาดใหญ่ พื้นผิวแข็งพิเศษ และแรงดึงสูงสุด เหมาะสำหรับทั้งสายพานขนส่งอ้อยหลักและการขนส่งกากอ้อย',
      'sug-p3-h3':        'HS Chain &mdash; Sugar Mill Series',
      'sug-p3-p':         'HS Chain เกาหลีเกรดทนการกัดกร่อน สำหรับสายพานลำเลียงกลาง โซ่ลิฟต์ และอุปกรณ์จัดการน้ำ ใช้งานแพร่หลายในโรงงานน้ำตาลทั่วเอเชียตะวันออกเฉียงใต้ ผ่านการพิสูจน์ตลอดฤดูเก็บเกี่ยว',
      'sug-tech-h2':      'คู่มือการเลือกโซ่โรงงานน้ำตาล',
      'sug-faq-h2':       'โซ่โรงงานน้ำตาล &mdash; คำถามที่พบบ่อย',
      'sug-faq-q1':       'ขนาดพิตช์โซ่สำหรับสายพานขนส่งอ้อยคืออะไร?',
      'sug-faq-a1':       'โซ่ขนส่งอ้อยทั่วไปใช้พิตช์ 66.7mm ถึง 102mm (P.102) ขึ้นอยู่กับการออกแบบสายพานและผู้ผลิตอุปกรณ์ พิตช์และจำนวนสตรันด์กำหนดตามความกว้างสายพาน โหลดออกแบบ และความเร็ว วิศวกร MPC จะระบุสเปคให้ตามแบบอุปกรณ์หรือขนาดโซ่เดิม',
      'sug-faq-q2':       'ควรเปลี่ยนโซ่โรงงานน้ำตาลช่วงไหนดีที่สุด?',
      'sug-faq-a2':       'ช่วงที่ดีที่สุดคือปิดโรงงานระหว่างฤดู (โดยทั่วไปเมษายนถึงตุลาคม) ซึ่งมีเวลาตรวจสอบอย่างละเอียด วัดการยืดตัว (เปลี่ยนที่ 2–3%) และสั่งซื้อล่วงหน้าก่อนฤดูเก็บเกี่ยวถัดไป MPC ช่วยวางแผนบำรุงรักษาและรับประกันว่าโซ่พร้อมก่อนเปิดฤดู',
      'sug-faq-q3':       'MPC จำหน่ายโซ่ให้โรงงานน้ำตาลในภาคอีสานได้หรือไม่?',
      'sug-faq-a3':       'ได้ครับ โรงงานน้ำตาลส่วนใหญ่ของไทยอยู่ในภาคอีสานและภาคเหนือ เราจัดส่งให้ทุกภูมิภาคจากคลังสินค้ากรุงเทพ สำหรับความต้องการเร่งด่วนในฤดูเก็บเกี่ยว เรารักษาสต็อกสเปคมาตรฐาน ติดต่อเราแต่เนิ่นๆ ในช่วงปิดฤดูเพื่อจองสินค้าล่วงหน้า',
      'sug-faq-q4':       'MPC ให้คำปรึกษาทางเทคนิคสำหรับการเลือกโซ่โรงงานน้ำตาลหรือไม่?',
      'sug-faq-a4':       'ให้ครับ ทีมงานเทคนิคของเราให้คำปรึกษาฟรีสำหรับงานโรงงานน้ำตาล เราวิเคราะห์พารามิเตอร์การใช้งาน &mdash; การออกแบบสายพาน กำลังการผลิต ความเร็วโซ่ สภาพแวดล้อม &mdash; และแนะนำสเปคที่เหมาะสมที่สุด ติดต่อเราพร้อมแบบทางเทคนิคหรือรายละเอียดโซ่เดิม',
      'sug-cta-h2':       'เตรียมโรงงานน้ำตาลให้พร้อมก่อนเปิดฤดู',
      'sug-cta-p':        'อย่ารอจนเริ่มฤดูเก็บเกี่ยว วางแผนเปลี่ยนโซ่ล่วงหน้า — ทีมเราช่วยด้านสเปค สต็อกสินค้า และราคา',

      /* ===== CEMENT INDUSTRY ===== */
      'cem-ind-badge':        '🏗️ ซีเมนต์และวัสดุก่อสร้าง',
