      'faq-q8': 'MPC ផ្ដល់ខ្សែច្រងសម្រាប់ Food-Grade Applications ឬទេ?',
      'faq-a1': 'MPC ឯកទេសសម្រាប់ <strong>ឧស្សាហកម្មដែក</strong>, <strong>ផលិតកម្មស៊ីម៉ង់</strong>, <strong>ការកិនប្រេងចំការ</strong> និង <strong>ការដំណើរការស្ករ</strong>។ ក្រៅពីនេះ យើងក៏បម្រើ Escalator Maintenance, Animal Feed Mills, Automotive Manufacturing និងរោងចក្រ Industrial ទូទៅ',
      'faq-a2': 'MPC ជាអ្នកចែកចាយ:<ul><li><strong>IWIS</strong> (អាល្លឺម៉ង់) &mdash; Precision Engineering Chains</li><li><strong>HS Chain</strong> (ចិន) &mdash; Heavy Conveyor &amp; Industrial Chains</li><li><strong>KMH</strong> (អាល្លឺម៉ង់) &mdash; Pipe Conveyor Systems</li><li><strong>Dongbo</strong> (កូរ៉េ) &mdash; ANSI Certified Standard Roller Chains</li></ul>ហើយម៉ាកផ្ទាល់ខ្លួន <strong>UNO Chain</strong> និង <strong>TRIO Chain</strong>',
      'faq-a3': 'បាទ/ចាស &mdash; After-Sales Service គឺជាផ្នែកសំខាន់របស់ MPC យើងផ្ដល់ការប្រឹក្សាបច្ចេកទេស ការវិភាគ Chain Failure និងសម្របសម្រួលជាមួយអ្នកផលិត ដើម្បីដោះស្រាយបញ្ហាប្រកបដោយប្រសិទ្ធភាព',
      'faq-a4': 'យើងដឹកជញ្ជូនទូទាំង <strong>ប្រទេសថៃ</strong> ហើយក៏បម្រើអតិថិជននៅទូទាំងអាស៊ីអាគ្នេយ៍ ដូចជា ម្យ៉ាន់ម៉ា ឡាវ កម្ពុជា វៀតណាម និង ASEAN',
      'faq-a5': 'ក្រុមបច្ចេកទេសរបស់យើងជ្រើសខ្សែច្រងត្រឹមត្រូវ ដោយផ្អែកលើ: Load Capacity, Operating Speed, Temperature Range, Chemical Exposure &mdash; ដោយឥតគិតថ្លៃ',
      'faq-a6': 'MPC ផ្ដល់ខ្សែច្រងតាមមាតចំណាត់ ANSI B29.1, ISO 606, DIN 8187/8188 និង JIS B1801',
      'faq-a7': 'សម្រាប់ Standard Items យើងឆ្លើយតបក្នុង <strong>ថ្ងៃធ្វើការមួយ</strong>។ ទំនាក់ទំនង contact@motionpluscorp.com ឬ <a href="tel:022865656">02 286-5656</a>',
      'faq-a8': 'បាទ/ចាស យើងផ្ដល់ Food-Grade ខ្សែច្រងសម្រាប់ការផលិតប្រេងចំការ ការបន្ថុំស្ករ និង Food Industry ផ្សេងៗ ដោយប្រើ Food-Safe Lubricants, Stainless Steel Pins',

