      'dbo-cbadge5':   '1 / 2 / 3 ស្រប',
      'dbo-desc-text': '<p>ខ្សែច្រងលំហូរ Pitch តូចត្រូវបានប្រើប្រាស់នៅក្នុងការអនុវត្តន៍ជាច្រើន ដូចជា ការវេចខ្ចប់ អាហារ គ្រឿងសំអាង ឱសថ ការផលិត និងឧស្សាហកម្មផ្សេងៗទៀត ខ្សែច្រងទាំងនេះផលិតពីសមាសភាគនៃខ្សែច្រង Roller ស្ដង់ដារ និង Attachment ដែលរចនាពិសេសសម្រាប់ការដឹកជញ្ជូន</p><ul><li>Attachment ស្ដង់ដារ និង Wide Contour មានក្នុងទំហំជាច្រើន</li><li>ខ្សែច្រង និងផ្នែកផ្សំជាច្រើនប្រភេទ មានស្ដុក ដើម្បីសម្រួលការដឹកជញ្ជូន</li><li>វត្ថុធាតុដើមប្រើ Carbon Steel, Stainless Steel, Plastic វិស្វកម្ម ជាមួយការលាបការពារ (Nickel, Zinc, Chromium, Dacrotized Coating)</li><li>Attachment ពិសេស អាចផ្ដល់ទៅតាមការបញ្ជាទិញពិសេស</li></ul><p class="pull">Dong Bo ក្នុងនាមជាអ្នកដឹកនាំក្នុងការផលិតខ្សែច្រងកូរ៉េ ដែលមានបទពិសោធន៍ 45+ ឆ្នាំ អាចជួយអ្នករកដំណោះស្រាយល្អបំផុតសម្រាប់ប្រព័ន្ធដឹកជញ្ជូន</p>',
