      'trio-desc-p1':        'ໂສ້ Forged ຄຸນນະພາບສູງ ທີ່ອອກແບບມາໂດຍສະເພາະສຳລັບລະບົບສາຍພານລຳເລີຍທຸກປະເພດ ໂດຍສະເພາະອຸດສາຫະກຳງານໜັກ ເຊັ່ນ ໂຮງງານເຫຼັກ ໂຮງງານປູນຊີເມັນ ແລະ ໂຮງງານອາຫານສັດ',
      'trio-desc-p2':        'Forged Chain TRIO (Pitch 102 ມມ) ແລະ Forged Chain UNO (Pitch 142 ມມ) ສາມາດຮັບນ້ຳໜັກໄດ້ສູງ ທົນຕໍ່ການສຶກຫໍ່ ທົນຕໍ່ການໃຊ້ງານໃນລາງ ທົນຄວາມຮ້ອນສູງ ແລະ ສະພາບແວດລ້ອມທີ່ມີຝຸ່ນ',
      'trio-desc-p3':        'Forged Chain TRIO &amp; UNO ຜະລິດຈາກເຫຼັກກ້າຄຸນນະພາບສູງ ຜ່ານກະບວນການ Forging ໃນຄວາມຮ້ອນສູງ ພ້ອມການອົບຊຸບຄວາມຮ້ອນຢ່າງເໝາະສົມ ຜ່ານກະບວນການ Machining ຂອງຂໍ້ໂສ້ ພ້ອມ Pin ແລະ Clip Lock ສຳລັບການຕິດຕັ້ງທີ່ສະດວກ',
